<template>
  <div class="mobile-input-container" :class="{ 
    'has-files': uploadFiles.length > 0,
    'has-upload-button': showUploadButton 
  }">
    <!-- 使用Element Plus X的Sender组件 -->
    <Sender
    ref="senderRef"
    v-model="inputValue"
    variant="updown"
    :auto-size="{ minRows: 2, maxRows: 12 }"
    :clearable="false"
    :allow-speech="false"
    :show-updown="true"
    :placeholder="$t('askAnything')"
      @submit="handleSubmit"
    >
      <!-- 输入框头部 - 显示上传文件 -->
      <template #header>
        <div v-if="uploadFiles.length > 0" class="upload-files-container">
          <div class="upload-files-scroll-wrapper">
            <!-- 显示所有文件 -->
            <div 
              v-for="(file, index) in uploadFiles" 
              :key="file.id"
              class="upload-file-card"
            >
              <!-- 文件卡片背景 -->
              <div class="file-card-bg">
                <!-- 文件图标或预览 -->
                <div class="file-display">
                  <!-- 如果是图片，显示预览 -->
                  <mobile-l-img
                    v-if="isImageFile(file) && !file.isLoading"
                    :src="file.url || file.previewUrl"
                    class="file-preview-image"
                    w="80px"
                    h="80px"
                    :enable-preview="true"
                    :preview-list="getImagePreviewList()"
                    :preview-index="getImageIndex(index)"
                    @click="handleImagePreview(file, index)"
                  />
                  
                  <!-- 如果是文档或加载中，显示通用文件图标 -->
                  <div v-else class="file-icon-container">
                    <mobile-l-img 
                      v-if="file.isLoading"
                      src="/static/images/file_loading.png" 
                      w="20px" 
                      h="20px" 
                      class="loading-icon" 
                    />
                    <mobile-l-img 
                      v-else
                      :src="getFileIcon(file)" 
                      w="20px" 
                      h="20px" 
                      class
                    />
                    <!-- 文件名显示 -->
                    <div v-if="!file.isLoading" class="file-name">
                      {{ file.name }}
                    </div>
                  </div>
                </div>
                
                <!-- 删除按钮 -->
                <div class="file-delete-btn" @click="handleDeleteFile(index)">
                  <mobile-l-img src="/static/mobile_images/mobile-upload-close.png" w="16px" h="16px" />
                </div>
              </div>
            </div>
          </div>
        </div>
      </template>
      
      <!-- 自定义前缀区域 - 左侧功能按钮 -->
      <template #prefix>
        <div ref="prefixActionsContainerRef" class="prefix-actions-container">
          <!-- Upload files悬浮按钮 -->
          <div v-if="showUploadButton" class="upload-files-floating-btn" @click="clickUploadFiles">
            <mobile-l-img src="/static/mobile_images/mobile-upload-f.png" w="14px" h="14px"/>
            <span class="upload-files-text">{{ $t('uploadFiles') }}</span>
          </div>
          
                      <!-- 上传选项弹窗 - 注释掉，改为直接使用浏览器默认选择器 -->
            <!-- <div v-if="showUploadOptions" class="upload-options-popup">
              <div class="upload-option" @click="handlePhotoGallery">
                <span class="option-text">{{ $t('photoGallery') }}</span>
                <div class="option-icon">
                  <mobile-l-img src="/static/mobile_images/mobile-upload-image.png" w="20px" h="20px"/>
                </div>
              </div>
              
              <div class="upload-option" @click="handleTakePhoto">
                <span class="option-text">{{ $t('takePhotosOrVideos') }}</span>
                <div class="option-icon">
                  <mobile-l-img src="/static/mobile_images/mobile-upload-carmer.png" w="20px" h="20px"/>
                </div>
              </div>
              
              <div class="upload-option" @click="handleSelectFile">
                <span class="option-text">{{ $t('selectFile') }}</span>
                <div class="option-icon">
                  <mobile-l-img src="/static/mobile_images/mobile-upload-files.png" w="20px" h="20px"/>
                </div>
              </div>
            </div> -->
          
          <div class="prefix-actions">
            <!-- 附件按钮 -->
            <div class="action-btn" @click="clickAttach">
              <mobile-l-img src="/static/images/conversation/file_extra.png" w="14px" h="14px"/>
            </div>
          
          <!-- 搜索按钮 -->
          <div 
            class="action-btn"
            :class="{ 'action-selected': isSearchModeChoose }"
            @click="clickSearch"
          >
            <mobile-l-img :src="searchIconSrc" w="14px" h="14px"/>
            <span v-if="isSearchModeChoose">{{ $t('deepSearch') }}</span>

          </div>
          
          <!-- 思考按钮 -->
          <div 
            class="action-btn"
            :class="{ 'action-selected': isThinking }"
            @click="clickThink"
          >
            <mobile-l-img :src="thinkIconSrc" w="14px" h="14px"/>
            <span v-if="isThinking">{{ $t('think') }}</span>
          </div>
        </div>
        </div>
      </template>

      <!-- 自定义操作列表 - 右侧发送按钮 -->
      <template #action-list>
        <div class="action-list">
          <mobile-l-send-button
            :is-can-send="canSend"
            :is-loading="isLoading"
            :is-chat="true"
            @onClickSend="clickSend"
            @onClickStop="clickSendStop"
          />
        </div>
      </template>
      

    </Sender>
    
    <!-- 隐藏的文件输入框 -->
    <input 
      ref="fileInputRef" 
      type="file" 
      style="display: none" 
      @change="handleFileSelect" 
    />
  </div>
</template>

<script setup>
// 引入区域
import MobileLSendButton from '@/mobile/components/mobile-l-send-button.vue';
import { Sender } from 'vue-element-plus-x'
import MobileLImg from '@/mobile/components/mobile-l-img.vue';

import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';
import { useAIChatStore } from '@/store/modules/AIChat';
import { ALLOWED_FILE_TYPES, FILE_ICON_MAP } from '@/types/upload.ts';
import { uploadImage, uploadDocument } from '@/api/upload/upload-service';
import { getImageDimensions } from '@/utils/util';
import { showMessageText } from '@/utils/mobile-ui-feedback';

// props区域
const props = defineProps({
  width: {
    type: String,
    default: "",
  },
  isSend: {
    type: Boolean,
    default: false,
  },
  initialThinking: {
    type: Boolean,
    default: false,
  },
  initialEnableSearch: {
    type: Boolean,
    default: false,
  },
});

// emits区域
const emit = defineEmits(["onSend", "onSendStop"]);

// 变量区域
const aiChatStore = useAIChatStore();
const { t } = useI18n();
const senderRef = ref();
const prefixActionsContainerRef = ref();
const fileInputRef = ref();
const inputValue = ref("");
const isLoading = ref(false);
const isThinking = ref(false);
const isSearchModeChoose = ref(false);
const uploadFiles = ref([]); // 上传文件列表
const showUploadButton = ref(false); // 是否显示Upload files按钮
const showUploadOptions = ref(false); // 是否显示上传选项
let fileIdCounter = 0; // 文件ID计数器，确保每个文件都有唯一ID

// 计算属性区域
const canSend = computed(() => {
  return inputValue.value.trim() !== '' && !isLoading.value;
});

const searchIconSrc = computed(() => {
  return isSearchModeChoose.value
    ? "/static/images/mobile-search-active.png"
    : "/static/images/conversation/search_icon.png";
});

const thinkIconSrc = computed(() => {
  return isThinking.value
    ? "/static/images/mobile-think-active.png"
    : "/static/images/conversation/think_icon.png";
});

// 点击事件区域
const clickAttach = () => {
  showUploadButton.value = !showUploadButton.value;
};

const clickUploadFiles = (event) => {
  // 阻止事件冒泡，避免立即触发全局点击
  event.stopPropagation();
  
  // 直接打开文件选择器，使用浏览器默认的"相机/相册/文件"选择界面
  if (fileInputRef.value) {
    // todo pxy 暂时只能上传图片
    fileInputRef.value.accept = ALLOWED_FILE_TYPES.IMAGE.join(',');
    fileInputRef.value.removeAttribute('capture'); // 不强制特定模式
    fileInputRef.value.multiple = true; // 允许多选
    fileInputRef.value.click();
  }
  
  // 隐藏Upload files按钮
  showUploadButton.value = false;
  
  // 原有显示选项弹窗的逻辑（已停用）
  // showUploadOptions.value = true;
};

const handlePhotoGallery = () => {
  // 打开相册选择图片
  if (fileInputRef.value) {
    fileInputRef.value.accept = ALLOWED_FILE_TYPES.IMAGE.join(',');
    fileInputRef.value.removeAttribute('capture'); // 完全移除capture属性，确保打开相册而不是摄像头
    fileInputRef.value.multiple = true; // 允许多选
    fileInputRef.value.click();
  }
  // 隐藏选项和按钮
  showUploadOptions.value = false;
  showUploadButton.value = false;
};

const handleTakePhoto = () => {
  // 打开摄像头拍照/录像
  if (fileInputRef.value) {
    fileInputRef.value.accept = [...ALLOWED_FILE_TYPES.IMAGE, ...ALLOWED_FILE_TYPES.VIDEO].join(',');
    fileInputRef.value.capture = 'environment';
    fileInputRef.value.multiple = true; // 允许多选
    fileInputRef.value.click();
  }
  // 隐藏选项和按钮
  showUploadOptions.value = false;
  showUploadButton.value = false;
};

const handleSelectFile = () => {
  // 选择任意支持的文件类型
  if (fileInputRef.value) {
    fileInputRef.value.accept = [...ALLOWED_FILE_TYPES.IMAGE, ...ALLOWED_FILE_TYPES.DOCUMENT].join(',');
    fileInputRef.value.removeAttribute('capture'); // 完全移除capture属性，确保打开文件选择器
    fileInputRef.value.multiple = true; // 允许多选
    fileInputRef.value.click();
  }
  // 隐藏选项和按钮
  showUploadOptions.value = false;
  showUploadButton.value = false;
};

const clickSearch = () => {
  isSearchModeChoose.value = !isSearchModeChoose.value;
  
  // 如果选择了搜索模式，取消Think模式（互斥）
  if (isSearchModeChoose.value && isThinking.value) {
    isThinking.value = false;
  }
  
  // 更新aiChatStore中的搜索状态
  const currentParams = aiChatStore.getAIChatParams() || {};
  aiChatStore.setAIChatParams({
    ...currentParams,
    enable_search: isSearchModeChoose.value,
    isThinking: isThinking.value
  });
};

const clickThink = () => {
  isThinking.value = !isThinking.value;
  
  // 如果选择了Think模式，取消搜索模式（互斥）
  if (isThinking.value && isSearchModeChoose.value) {
    isSearchModeChoose.value = false;
  }
  
  // 更新aiChatStore中的Think状态
  const currentParams = aiChatStore.getAIChatParams() || {};
  aiChatStore.setAIChatParams({
    ...currentParams,
    isThinking: isThinking.value,
    enable_search: isSearchModeChoose.value,
  });
};

const clickMenu = () => {
  console.log('Menu clicked');
  // 暂时不实现菜单逻辑
};

const clickSend = () => {
  if (props.isSend || !canSend.value) return;
  
  isLoading.value = true;
  
  // 获取当前所有选择的参数
  const params = getCurrentSelectParams();
  
  // 发送消息事件
  emit("onSend", params);
  
  // 清空输入框
  inputValue.value = "";
};

const clickSendStop = () => {
  isLoading.value = false;
  emit("onSendStop");
};

// 业务逻辑区域
const handleSubmit = () => {
  clickSend();
};

// 图片预览相关方法
const handleImagePreview = (file, index) => {
  // 图片预览功能已由mobile-l-img组件内置的enablePreview实现
  console.log('Preview image:', file.name, 'at index:', index);
};

const getImagePreviewList = () => {
  // 只返回已上传完成的图片文件
  return uploadFiles.value
    .filter(file => isImageFile(file) && !file.isLoading)
    .map(file => file.url || file.previewUrl);
};

const getImageIndex = (originalIndex) => {
  // 计算当前图片在图片列表中的索引
  let imageIndex = 0;
  for (let i = 0; i < originalIndex; i++) {
    if (isImageFile(uploadFiles.value[i]) && !uploadFiles.value[i].isLoading) {
      imageIndex++;
    }
  }
  return imageIndex;
};

// 数据解析区域
const getCurrentSelectParams = () => {
  return {
    isThinking: isThinking.value,
    content: inputValue.value,
    files: uploadFiles.value.filter((file) => !file.isLoading), // 只发送已上传完成的文件
    enable_search: isSearchModeChoose.value,
  };
};

// 文件处理相关方法
const isImageFile = (file) => {
  const fileType = file.type || "";
  return ALLOWED_FILE_TYPES.IMAGE.includes(fileType);
};

const isSupportedFile = (file) => {
  const fileType = file.type || "";
  return [...ALLOWED_FILE_TYPES.IMAGE, ...ALLOWED_FILE_TYPES.DOCUMENT].includes(fileType);
};

const isVideoFile = (file) => {
  const fileType = file.type || "";
  return ALLOWED_FILE_TYPES.VIDEO.includes(fileType);
};

const getFileIcon = (file) => {
  const type = file.type || "";
  return FILE_ICON_MAP[type] || "/static/images/error_file_icon.png";
};

// 文件上传处理
const handleFileSelect = (event) => {
  const files = event.target.files;
  if (files && files.length > 0) {
    const fileArray = Array.from(files);
    
    // 预先检查文件数量限制
    const totalFiles = uploadFiles.value.length + fileArray.length;
    if (totalFiles > 10) {
      const canAdd = 10 - uploadFiles.value.length;
      if (canAdd <= 0) {
        showMessageText(t("maxFilesReached", { max: 10 }));
        return;
      } else {
        showMessageText(t("maxFilesReachedWithDetails", { 
          selected: fileArray.length, 
          canAdd: canAdd, 
          max: 10 
        }) || `You selected ${fileArray.length} files, but only ${canAdd} more files can be added (max 10 total)`);
        // 只处理可以添加的文件数量
        fileArray.splice(canAdd);
      }
    }
    
    // 处理多个文件
    fileArray.forEach(file => {
      handleFileSelected(file);
    });
  }
  // 重置输入框，允许重复选择同一文件
  event.target.value = '';
};

const handleFileSelected = async (file) => {
  // 检查文件类型
  console.log(file);
  if (!isImageFile(file) && !isSupportedFile(file) && !isVideoFile(file)) {
    showMessageText(t("fileTypeNotAllowedWithName", { name: file.name }));
    return;
  }

  // 创建唯一ID，确保多文件同时上传时不会冲突
  const uniqueId = `${Date.now()}_${++fileIdCounter}_${Math.random().toString(36).substr(2, 9)}`;

  // 创建文件对象
  const fileObj = {
    id: uniqueId,
    name: file.name,
    type: file.type,
    size: file.size,
    file: file,
    isLoading: true,
    url: null,
    mediaId: null,
    previewUrl: null
  };

  // 如果是图片，创建预览URL
  if (isImageFile(file)) {
    fileObj.previewUrl = URL.createObjectURL(file);
  }

  // 添加到上传列表
  uploadFiles.value.push(fileObj);

  // 隐藏Upload files按钮（如果正在显示）
  showUploadButton.value = false;

  // 打开header显示文件
  await nextTick();
  senderRef.value?.openHeader();

  // 执行真实文件上传
  await realFileUpload(fileObj);
};

// 真实文件上传过程
const realFileUpload = async (fileObj) => {
  try {
    let uploadResult;

    // 根据文件类型选择上传方法
    if (isImageFile(fileObj) || isVideoFile(fileObj)) {
      // 如果是图片，视频，传递尺寸信息
      const dimensions = fileObj.previewUrl ? await getImageDimensions(fileObj.previewUrl) : null;
      uploadResult = await uploadImage(fileObj.file, true, dimensions);
    } else {
      // 如果是文档
      uploadResult = await uploadDocument(fileObj.file);
    }

    const index = getFileIndex(fileObj);
    if (index !== -1) {
      // 更新文件状态为上传完成
      uploadFiles.value[index].isLoading = false;
      uploadFiles.value[index].url = uploadResult.url;
      uploadFiles.value[index].mediaId = uploadResult.mediaId;
    }
  } catch (error) {
    console.error('File upload failed:', error);

    const index = getFileIndex(fileObj);
    if (index !== -1) {
      // 上传失败，移除文件
      handleDeleteFile(index);
    }
  }
};

// 获取文件在原始数组中的索引
const getFileIndex = (file) => {
  return uploadFiles.value.findIndex((f) => f.id === file.id);
};

// 处理文件删除
const handleDeleteFile = (index) => {
  const file = uploadFiles.value[index];
  
  // 如果是图片且有预览URL，释放内存
  if (file && file.previewUrl && isImageFile(file)) {
    URL.revokeObjectURL(file.previewUrl);
  }

  // 删除文件
  uploadFiles.value.splice(index, 1);

  // 如果没有文件了，关闭header
  if (uploadFiles.value.length === 0) {
    senderRef.value?.closeHeader();
  }
};



// 初始化方法区域
const initData = () => {
  if (props.initialThinking) {
    isThinking.value = props.initialThinking;
  }
  if (props.initialEnableSearch) {
    isSearchModeChoose.value = true;
  }
};

// 全局点击处理 - 点击其他区域隐藏相关弹窗
const handleGlobalClick = (event) => {
  if (!showUploadButton.value && !showUploadOptions.value) return;
  
  // 检查点击的目标是否在相关元素内
  const prefixContainer = prefixActionsContainerRef.value;
  if (prefixContainer && !prefixContainer.contains(event.target)) {
    showUploadButton.value = false;
    showUploadOptions.value = false;
  }
};

// 周期函数区域
onMounted(() => {
  initData();
  // 添加全局点击监听器
  document.addEventListener('click', handleGlobalClick);
});

onUnmounted(() => {
  // 移除全局点击监听器
  document.removeEventListener('click', handleGlobalClick);
});

// 监听props变化
watch(
  () => props.initialThinking,
  (newVal) => {
    isThinking.value = newVal;
  }
);

watch(
  () => props.initialEnableSearch,
  (newVal) => {
    isSearchModeChoose.value = newVal;
  }
);

// 导出区域
defineExpose({
  isLoading,
});
</script>

